  {"model": "SmolLM2-135M/360M/1.7B", "reason": "Only base and final Instruct published. No SFT-only or DPO-only checkpoint. Pre-training intermediates exist but alignment intermediates do not."},
  {"model": "Qwen2.5-0.5B-Instruct", "reason": "Only Base and Instruct published. No intermediate alignment checkpoints."},
  {"model": "Pythia (base)", "reason": "154 pretraining checkpoints per size, but EleutherAI did not perform alignment. Need third-party aligned variants."}
],

"feasibility_assessment": {
  "recommended_primary": "OLMo-2-0425-1B",
  "why": "1B params = ~4GB fp32, feasible on CPU. 4 alignment stages (Base→SFT→DPO→Instruct). Apache-2.0. Established in literature (Karouzos et al. 2026 used OLMo for diversity collapse analysis).",
  "recommended_secondary": "SmolLM3-3B-checkpoints",
  "cpu_inference_estimate": {
    "OLMo-2-1B_fp32": "~3-5 tokens/sec on modern CPU, ~200 tokens in 40-60 sec per prompt",
    "SmolLM3-3B_int8": "~1-2 tokens/sec on CPU, slower but feasible for small eval sets",
    "generation_budget": "1000 prompts × 4 stages × 200 tokens = 800K tokens. At ~4 tok/s = ~55 hours for OLMo-1B. Recommend subsampling to 100-200 prompts."
  },
  "gpu_alternative": "If GPU available: run full 1000 prompts in ~2-4 hours total across all stages.",
  "self_train_fallback": "If no satisfactory checkpoints: fine-tune Pythia-410M or SmolLM-135M with TRL DPO on UltraFeedback, save per-epoch checkpoints. Requires 1 GPU, ~2 hours. Recommend Director allocate if needed."
},

"experiment_design": {
  "eval_set": "WikiText-103 test, first 200 sentences (subsampled for CPU budget)",
  "generation_config": {
    "max_new_tokens": 200,
    "temperature": 1.0,
    "top_p": 0.95,
    "do_sample": true,
    "num_return_sequences": 5,
    "note": "T=1.0 to preserve natural diversity signal; 5 continuations per prompt for within-prompt diversity"
  },
  "checkpoints_to_evaluate": [
    "allenai/OLMo-2-0425-1B (Base)",
    "allenai/OLMo-2-0425-1B-SFT",
    "allenai/OLMo-2-0425-1B-DPO",
    "allenai/OLMo-2-0425-1B-Instruct"
  ],
  "metrics_per_stage": [
    "token_entropy (H) — Shannon entropy of next-token distribution",
    "distinct_1 / distinct_2 / distinct_3 — ratio of unique n-grams",
    "ECE — expected calibration error",
    "perplexity — on held-out text",
    "repetition_rate — fraction of repeated 4-grams in generations",
    "self_BLEU — intra-prompt generation similarity"
  ],
  "permg_application": {
    "concept": "Treat each alignment stage as a 'generation' in the PermG framework. The 4-stage sequence (Base→SFT→DPO→Instruct) is analogous to the multi-generation autoregressive degradation studied in the paper.",
    "analysis": [
      "Compute per-metric trajectories across 4 stages",
      "Run cross-correlation between entropy and distinct-n trajectories",
      "Test for lead-lag: does entropy decline precede distinct-n decline?",
      "Compute PermG K-value: how many stages until collapse threshold?"
    ],
    "limitation": "Only 4 stages (not the 10-20 generations in standard PermG). Statistical power is limited. Mitigate by: (1) using per-prompt metrics as repeated measures, (2) adding SmolLM3 as replication, (3) if RLVR step-level checkpoints give 10+ points, use those for finer-grained analysis."
  }
},

